const d = $input.first().json.demande;
const g = d.guide || {};
const c = d.contact;
const prochain = (jours) => { let x = maintenant().plus({ days: jours }).set({ hour: 9, minute: 30, second: 0 }); while (!estOuvrable(x)) x = x.plus({ days: 1 }); return x.toISO(); };
